<script setup lang="ts">
import type { DocumentRecord, Station, Page } from '~/utils/types'
const api=useApi();const {actor,courier,unitIds}=useSession();const station=ref('');const stations=ref<Station[]>([]);const docs=ref<DocumentRecord[]>([]);const cursor=ref<string|null>();const loading=ref(false);const saving=ref('');const error=ref<unknown>();const message=ref('')
async function load(more=false){if(!station.value)return;loading.value=true;error.value=undefined;try{const page=await api.get<Page<DocumentRecord>>(`/stations/${station.value}/worklist?limit=50${more&&cursor.value?`&cursor=${encodeURIComponent(cursor.value)}`:''}`);docs.value=more?[...docs.value,...page.items]:page.items;cursor.value=page.next_cursor}catch(e){error.value=e}finally{loading.value=false}}
async function reserve(doc:DocumentRecord){saving.value=doc.id;error.value=undefined;message.value='';try{await api.command('/courier/reservations',{station_id:station.value,items:[{document_id:doc.id,route_step_id:doc.current_route_step_id,expected_version:doc.version}]});message.value='จองหนังสือแล้ว ยังไม่ได้ Check รับและยังไม่เปลี่ยนผู้ถือครอง';await load()}catch(e){error.value=e}finally{saving.value=''}}
onMounted(async()=>{try{stations.value=(await api.get<Page<Station>>('/stations')).items.filter(s=>actor.value?.station_ids.includes(s.id));station.value=stations.value[0]?.id||'';await load()}catch(e){error.value=e}})
</script>
<template><div class="page-head"><div><h1>งานประจำ Station</h1><p>แสดงรายการตามสิทธิ์ Station ของคุณ Model A เป็นตำแหน่งรายงานล่าสุด ต้องตรวจของจริงก่อนรับ</p></div><NuxtLink v-if="courier" class="button" to="/reservations">การจองของฉัน</NuxtLink></div><Feedback :error="error" :message="message" /><section class="panel"><form class="actions" @submit.prevent="load()"><div class="field"><label for="work-station">Station</label><select id="work-station" v-model="station" required @change="docs=[];cursor=null;load()"><option disabled value="">เลือก Station</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}</option></select></div><button class="button" :disabled="loading||!station">โหลดล่าสุด</button></form><UProgress v-if="loading" /><div v-if="!docs.length&&!loading" class="empty"><h3>ไม่มีรายการใน Station นี้</h3><p>รายการแสดงตามสิทธิ์ สถานะหนังสือ และเงื่อนไขที่เซิร์ฟเวอร์ตรวจ</p></div><div class="table-wrap"><table v-if="docs.length"><thead><tr><th>หนังสือ</th><th>สถานะงาน</th><th>Workflow</th><th v-if="courier">จองรับ</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.id"><td><NuxtLink v-if="unitIds.includes(doc.origin_unit_id)" :to="`/documents/${doc.id}`">{{doc.title||doc.document_number}}</NuxtLink><span v-else class="row-title">หนังสือ #{{doc.id.slice(-8)}}</span><p class="hint">Model {{doc.tracking_mode}}</p></td><td><StatusTag :value="doc.business_state" /></td><td><StatusTag :value="doc.process_sync_status" /></td><td v-if="courier"><button class="button" :disabled="!!saving||doc.process_sync_status!=='APPLIED'" @click="reserve(doc)">{{saving===doc.id?'กำลังจอง…':'จองหนังสือนี้'}}</button><p v-if="doc.process_sync_status!=='APPLIED'" class="hint">รอ workflow พร้อมใช้งาน</p></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดงานเพิ่มเติม</button></section></template>
